#include "main.h"

#include <stdio.h>
#include <stdlib.h>

#include "gba.h"
#include "images/you.h"
#include "images/enemy.h"
#include "images/winnerahhh.h"
#include "images/loserahhh.h"
#include "images/newback.h"
#include "images/start.h"
