// these specific provided states.

int timer = 0 ;
char timerString[16];

enum gba_state {
  START,
  PLAY,
  WIN,
  LOSE,
};

void initialize(struct rect *pP, struct ball *pBall, struct rect *pOffense) {

    timer = 0;
    vBlankCounter = 0;

    pP->row= 80;
    pP->col = 20;
    pP->width = 12;
    pP->height = 25;

    pBall->row = 80;
    pBall->col = 120;
    pBall->size = 3;
    pBall->velRow = 1;
    pBall->velCol = 1;

    pOffense->row = 80;
    pOffense->col = WIDTH -20;
    pOffense->width = 12;
    pOffense->height = 25;



}
int main(void) {
  /* TODO: */
  // Manipulate REG_DISPCNT here to set Mode 3. //
  REG_DISPCNT = MODE3 | BG2_ENABLE;
  // Save current and previous state of button input.
  u32 previousButtons = BUTTONS;
  u32 currentButtons = BUTTONS;

  struct rect player;

  struct ball b;

  struct rect offense;


  initialize(&player, &b, &offense);


  // Load initial application state
  enum gba_state state = START;
  drawFullScreenImageDMA(start);

  while (1) {
    currentButtons = BUTTONS; // Load the current state of the buttons
    /* TODO: */
    // Manipulate the state machine below as needed //
    // NOTE: Call waitForVBlank() before you draw
    waitForVBlank();
    if(KEY_JUST_PRESSED(BUTTON_SELECT, currentButtons, previousButtons)) {
        state = START;
        drawFullScreenImageDMA(start);
        initialize(&player, &b, &offense);
    }
    switch (state) {
      case START:
        if(KEY_JUST_PRESSED(BUTTON_START, currentButtons, previousButtons)) {
            state = PLAY;
            drawFullScreenImageDMA(newback);
        }

        // state = ?
        break;
      case PLAY:
        timer += 2;
        undrawImageDMA(12, WIDTH / 2, 25,10, newback);
        drawRectDMA(10, (WIDTH/ 2) - 2, 55, 12, RED);
        sprintf(timerString, "Timer:%02d" , (timer/60) % 60);
        drawString(12, WIDTH/2, timerString, GREEN);

        if(timer > 100000) {
            state = WIN;
            drawFullScreenImageDMA(winnerahhh);
            break;
        }
        waitForVBlank();


        undrawImageDMA(player.row, player.col, player.width, player.height, newback);
        undrawImageDMA(offense.row, offense.col, offense.width, offense.height, newback);
        undrawImageDMA(b.row, b.col, b.size, b.size, newback);

        if(vBlankCounter % 600 == 0) {
            if (b.velCol > 0) {
                b.velCol++;
            } else {
                b.velCol--;

            }
            if (b.velRow > 0) {
                b.velRow++;
            } else {
                b.velRow--;
            }
        }
        if (KEY_DOWN(BUTTON_UP, currentButtons)) {
            if (player.row -1 < 0) {
                player.row = 0;
            } else {
                player.row -= 3;
            }
        }

        if (KEY_DOWN(BUTTON_DOWN, currentButtons)) {
            if(player.row + player.height + 1 > HEIGHT) {
                player.row = HEIGHT - player.height;

            } else {
                player.row += 3;
            }

        }

        if (b.row + b.velRow < 0) {
            b.velRow *= -1;

        }


        if (b.row + b.velRow + b.size > HEIGHT) {
            b.velRow *= -1;
        }

        if (b.col + b.velCol < 0) {
            state = LOSE;
            drawFullScreenImageDMA(loserahhh);
            break;

        }
        if (b.col + b.velCol + b.size > WIDTH) {
            state = WIN;
            drawFullScreenImageDMA(winnerahhh);
            break;

        }

        if (rectColl(player, b) || rectColl(offense, b)) {
            b.velCol *= -1;
        }

        int enemyCenRow = offense.row + offense.height / 2;
        if (b.row > enemyCenRow) {
            if(offense.row + offense.height + 1 > HEIGHT) {
                offense.row = HEIGHT - offense.height;
            } else {
                offense.row += 1;
            }
        }
        if (b.row < enemyCenRow) {
            if ( offense.row -1 < 0) {
                offense.row = 0;
            } else {
                offense.row -=1;
            }
        }


        b.row += b.velRow;
        b.col += b.velCol;
        drawImageDMA(player.row, player.col, player.width, player.height, you);
        drawImageDMA(offense.row, offense.col, offense.width, offense.height, enemy);
        drawRectDMA(b.row, b.col, b.size, b.size, WHITE);
        // state = ?

        break;
      case WIN:
        timer = 0;


        // state = ?
        break;
      case LOSE:
        timer = 0;

        // state = ?
        break;
    }

    previousButtons = currentButtons; // Store the current state of the buttons
  }

  UNUSED(previousButtons); // You can remove this once previousButtons is used

  return 0;
}

int rectColl(struct rect player, struct ball b) {
    if ((player.col < b.col + b.size) && (player.col + player.width > b.col) && (player.row < b.row + b.size) && (player.row + player.height > b.row)) {
        return 1;

    } else {
        return 0;
    }
}
